+// chainGuardFor returns a Locals key shared by Chain.Extract and
+// extractChainWithSource for the public Chain backing array.
+func chainGuardFor(chain []Extractor) (chainGuardKey, bool) {
+	if len(chain) == 0 {
+		return chainGuardKey{}, false
+	}
