+	src := prev[len(prev)-1]
+	prev = prev[:len(prev)-1]
+	if len(prev) == 0 {
+		c.Locals(chainWinStackKey{}, nil)
+	} else {
+		c.Locals(chainWinStackKey{}, prev)
+	}
+	return src, true
