+// Test_Coverage_NewSSRFDialer_RejectsLoopbackHostname drives the
+// SplitHostPort → resolveAndValidateHost → blocked-IP rejection branch.
+func Test_Coverage_NewSSRFDialer_RejectsLoopbackHostname(t *testing.T) {
